function validate([poly1, poly2]) {
  for (const poly of [poly1, poly2]) {
    if (!Array.isArray(poly) || poly.length > 10000) return 'Each polynomial lists at most 10^4 terms.';
    for (let i = 0; i < poly.length; i++) {
      const term = poly[i];
      if (!Array.isArray(term) || term.length !== 2 || !Number.isInteger(term[0]) || !Number.isInteger(term[1])) return 'Each term is a [coefficient, power] pair of whole numbers.';
      if (term[0] === 0 || term[0] < -1000000000 || term[0] > 1000000000) return 'Coefficients are non-zero and between -10^9 and 10^9.';
      if (term[1] < 0 || term[1] > 1000000000) return 'Powers are between 0 and 10^9.';
      if (i > 0 && poly[i - 1][1] <= term[1]) return 'Powers must strictly decrease along each list.';
    }
  }
  return null;
}

adapter:
function adapt(input, solve, kit) {
  // LeetCode provides PolyNode; this is the same class.
  class PolyNode {
    constructor(x = 0, y = 0, next = null) {
      this.coefficient = x;
      this.power = y;
      this.next = next;
    }
  }
  globalThis.PolyNode = PolyNode;
  const build = terms => {
    let head = null;
    for (let i = terms.length - 1; i >= 0; i--) head = new PolyNode(terms[i][0], terms[i][1], head);
    return head;
  };
  const [poly1, poly2] = input;
  const result = solve(build(poly1), build(poly2));
  if (result === undefined) throw new Error('The solution did not return a value; return the head of the sum, or null.');
  const out = [];
  const limit = poly1.length + poly2.length;
  for (let node = result; node !== null; node = node.next) {
    if (typeof node !== 'object') throw new Error('Return PolyNode objects linked through next, ending in null.');
    if (out.length >= limit) throw new Error('The returned list is longer than the two inputs together, or it loops.');
    out.push([node.coefficient, node.power]);
  }
  return out;
}

