function addPoly(poly1, poly2) {
  const dummy = new PolyNode();
  let tail = dummy;
  let first = poly1;
  let second = poly2;

  while (first !== null && second !== null) {
    if (first.power > second.power) {
      tail.next = first;
      tail = first;
      first = first.next;
    } else if (first.power < second.power) {
      tail.next = second;
      tail = second;
      second = second.next;
    } else {
      const sum = first.coefficient + second.coefficient;
      if (sum !== 0) {
        tail.next = new PolyNode(sum, first.power);
        tail = tail.next;
      }
      first = first.next;
      second = second.next;
    }
  }
  tail.next = first !== null ? first : second;
  return dummy.next;
}

