function addPoly(poly1, poly2) {
  // Collect every term into a power -> coefficient table, then rebuild the list from the highest power.
  const totals = new Map();
  for (let node of [poly1, poly2]) {
    for (; node !== null; node = node.next) totals.set(node.power, (totals.get(node.power) || 0) + node.coefficient);
  }
  const powers = [...totals.keys()].filter(p => totals.get(p) !== 0).sort((a, b) => a - b);
  let head = null;
  for (const p of powers) head = new PolyNode(totals.get(p), p, head);
  return head;
}

