function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const coefMax = rand() < 0.3 ? 1000000000 : large ? 1000 : 3;
  const coef = () => (rand() < 0.5 ? -1 : 1) * int(1, coefMax);
  const top = large ? (rand() < 0.4 ? 1000000000 : 3000) : int(0, 6);
  const count = () => large ? int(1000, 2000) : int(0, 4);
  const pickPowers = n => {
    const chosen = new Set();
    for (let tries = 0; chosen.size < n && tries < 10 * n + 10; tries++) chosen.add(int(0, top));
    return [...chosen];
  };
  const byPower = (a, b) => b[1] - a[1];
  const poly1 = pickPowers(count()).map(p => [coef(), p]).sort(byPower);
  if (rand() < 0.1) return [poly1, poly1.map(([c, p]) => [-c, p])];
  // poly2 shares some of poly1's powers (sometimes cancelling them exactly) and adds its own.
  const terms = new Map();
  for (const [c, p] of poly1) if (rand() < 0.5) terms.set(p, rand() < 0.4 ? -c : coef());
  for (const p of pickPowers(count())) if (!terms.has(p)) terms.set(p, coef());
  const poly2 = [...terms].map(([p, c]) => [c, p]).sort(byPower).slice(0, large ? 2000 : 10);
  return rand() < 0.5 ? [poly1, poly2] : [poly2, poly1];
}
